error E:
  Bad:
    value:int
fn make(offset:int)->fn(int)->int ! E:
  fn(value):
    if value<0:
      fail E.Bad {value:offset}
    adjusted=value+offset
    adjusted
fn main()->int:
  f=make(21)
  a=f(-1) catch fn(error):
    match error:
      E.Bad {value}:value
  b=f(0) catch fn(error):0
  a+b
